solution.code:
class Akun {
  #saldo;

  constructor(pemilik, saldo = 0) {
    this.pemilik = pemilik;
    this.#saldo = saldo;
  }

  setor(n) {
    if (n <= 0) throw new Error("Jumlah harus positif");
    this.#saldo += n;
    return this.#saldo;
  }

  tarik(n) {
    if (n <= 0) throw new Error("Jumlah harus positif");
    if (n > this.#saldo) throw new Error("Saldo tidak cukup");
    this.#saldo -= n;
    return this.#saldo;
  }

  get total() {
    return this.#saldo;
  }
}

