function ambilEnv(env, kunci, bawaan) {
  const nilai = env[kunci];
  return nilai === undefined || nilai === "" ? bawaan : nilai;
}

function ambilPort(env) {
  const teks = ambilEnv(env, "PORT", "3000");
  const port = Number(teks);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error("PORT tidak valid: " + teks);
  return port;
}

project.brief:
Bangun **Toko Mini**: logika pengelola pesanan dengan pola-pola TypeScript yang sudah kamu pelajari: validasi data `unknown`, discriminated union, fungsi generik, dan class dengan field privat. Kodenya JavaScript murni (sandbox menjalankan JavaScript), dengan tipe yang ditulis sebagai komentar JSDoc di bawah ini. Tanpa DOM dan tanpa `fetch`.

## Tipe (dalam notasi TypeScript)

```ts
type Status = "baru" | "dibayar" | "dikirim" | "selesai" | "batal";
type Item = { sku: string; jumlah: number; harga: number };
type Pesanan = { id: number; pelanggan: string; item: Item[]; status: Status };
type Aksi = { jenis: "bayar" } | { jenis: "kirim" } | { jenis: "selesai" } | { jenis: "batal" };
type Hasil<T> = { ok: true; nilai: T } | { ok: false; galat: string };
```

## Fungsi dan class wajib

| Nama | Tugas |
| --- | --- |
| `parsePesanan(x)` | Terima `unknown`, kembalikan `Hasil<Pesanan>`. Galat (periksa berurutan): bukan object: `"data bukan object"`; `id` bukan bilangan bulat > 0: `"id tidak valid"`; `pelanggan` bukan string atau kosong setelah `trim()`: `"pelanggan wajib diisi"`; `item` bukan array berisi: `"item kosong"`; ada item dengan `sku` bukan string kosong, `jumlah` bukan bilangan bulat >= 1, atau `harga` bukan number >= 0: `"item tidak valid"`. `status` opsional (bawaan `"baru"`); nilai di luar `Status`: `"status tidak dikenal"`. `pelanggan` disimpan setelah `trim()`. |
| `totalPesanan(p)` | Jumlah `jumlah * harga` semua item. |
| `lanjutkan(p, aksi)` | Kembalikan pesanan **baru** (aslinya tidak berubah). Transisi: `baru` + `bayar` -> `dibayar`; `dibayar` + `kirim` -> `dikirim`; `dikirim` + `selesai` -> `selesai`; `baru` atau `dibayar` + `batal` -> `batal`. Transisi lain: `throw new Error("Transisi tidak diizinkan: " + p.status + " -> " + aksi.jenis)`. `jenis` tak dikenal: `throw new Error("Aksi tidak dikenal")`. |
| `kelompokkan(daftar, fn)` | Generik: `{ [kunci]: elemen[] }` berdasarkan `fn(elemen)`. |
| `class Toko` | Field privat `#pesanan`. `tambah(x)`: `parsePesanan`; bila sah dan `id` belum ada, simpan dan kembalikan hasilnya; id kembar: `{ ok: false, galat: "id sudah ada" }`. `ambil(id)`: pesanan atau `undefined`. `proses(id, aksi)`: `{ ok: true, nilai }` dengan pesanan baru yang disimpan, atau `{ ok: false, galat }` (pesan galat dari `lanjutkan`; id tidak ada: `"pesanan tidak ditemukan"`). `laporan()`: `{ jumlah, pendapatan, perStatus }`; `pendapatan` menjumlahkan total pesanan berstatus `dibayar`, `dikirim`, atau `selesai`; `perStatus` menghitung pesanan per status. |

## Contoh

```js
const toko = new Toko();
toko.tambah({ id: 1, pelanggan: " Sari ", item: [{ sku: "A1", jumlah: 2, harga: 5000 }] });
toko.proses(1, { jenis: "bayar" });          // { ok: true, nilai: { ..., status: "dibayar" } }
toko.proses(1, { jenis: "selesai" });        // { ok: false, galat: "Transisi tidak diizinkan: dibayar -> selesai" }
toko.laporan();                              // { jumlah: 1, pendapatan: 10000, perStatus: { dibayar: 1 } }
```

