solution.code:
/** @typedef {"baru"|"dibayar"|"dikirim"|"selesai"|"batal"} Status */
const STATUS = ["baru", "dibayar", "dikirim", "selesai", "batal"];

const gagal = (galat) => ({ ok: false, galat });

/** @param {unknown} x @returns {{ok: true, nilai: object} | {ok: false, galat: string}} */
function parsePesanan(x) {
  if (typeof x !== "object" || x === null) return gagal("data bukan object");
  if (!Number.isInteger(x.id) || x.id <= 0) return gagal("id tidak valid");
  if (typeof x.pelanggan !== "string" || x.pelanggan.trim() === "") return gagal("pelanggan wajib diisi");
  if (!Array.isArray(x.item) || x.item.length === 0) return gagal("item kosong");
  const itemValid = x.item.every(
    (i) =>
      typeof i === "object" && i !== null &&
      typeof i.sku === "string" && i.sku !== "" &&
      Number.isInteger(i.jumlah) && i.jumlah >= 1 &&
      typeof i.harga === "number" && i.harga >= 0
  );
  if (!itemValid) return gagal("item tidak valid");
  const status = x.status ?? "baru";
  if (!STATUS.includes(status)) return gagal("status tidak dikenal");
  return { ok: true, nilai: { id: x.id, pelanggan: x.pelanggan.trim(), item: x.item.map((i) => ({ sku: i.sku, jumlah: i.jumlah, harga: i.harga })), status } };
}

function totalPesanan(p) {
  return p.item.reduce((t, i) => t + i.jumlah * i.harga, 0);
}

const ALUR = { bayar: { baru: "dibayar" }, kirim: { dibayar: "dikirim" }, selesai: { dikirim: "selesai" }, batal: { baru: "batal", dibayar: "batal" } };

function lanjutkan(p, aksi) {
  const tabel = ALUR[aksi.jenis];
  if (!tabel) throw new Error("Aksi tidak dikenal");
  const baru = tabel[p.status];
  if (!baru) throw new Error("Transisi tidak diizinkan: " + p.status + " -> " + aksi.jenis);
  return { ...p, status: baru };
}

function kelompokkan(daftar, fn) {
  const hasil = {};
  for (const x of daftar) (hasil[fn(x)] ??= []).push(x);
  return hasil;
}

class Toko {
  #pesanan = [];

  tambah(x) {
    const hasil = parsePesanan(x);
    if (!hasil.ok) return hasil;
    if (this.#pesanan.some((p) => p.id === hasil.nilai.id)) return gagal("id sudah ada");
    this.#pesanan.push(hasil.nilai);
    return hasil;
  }

  ambil(id) {
    return this.#pesanan.find((p) => p.id === id);
  }

  proses(id, aksi) {
    const indeks = this.#pesanan.findIndex((p) => p.id === id);
    if (indeks === -1) return gagal("pesanan tidak ditemukan");
    try {
      const baru = lanjutkan(this.#pesanan[indeks], aksi);
      this.#pesanan[indeks] = baru;
      return { ok: true, nilai: baru };
    } catch (e) {
      return gagal(e instanceof Error ? e.message : String(e));
    }
  }

  laporan() {
    const berbayar = ["dibayar", "dikirim", "selesai"];
    const perStatus = {};
    let pendapatan = 0;
    for (const p of this.#pesanan) {
      perStatus[p.status] = (perStatus[p.status] ?? 0) + 1;
      if (berbayar.includes(p.status)) pendapatan += totalPesanan(p);
    }
    return { jumlah: this.#pesanan.length, pendapatan, perStatus };
  }
}
